import{_ as l,l as o,o as e,c as s,v as r,p as n,x as t,d as p,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"CIA 三元组","description":"","frontmatter":{"title":"CIA 三元组","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cia-triad.md","filePath":"cs/cia-triad.md","lastUpdated":1789023840000}'),c={name:"cs/cia-triad.md"};function h(E,a,C,_,m,u){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="cia-三元组" tabindex="-1">CIA 三元组 <a class="header-anchor" href="#cia-三元组" aria-label="Permalink to &quot;CIA 三元组&quot;">​</a></h1><div class="epigraph"><p>保密、完整、可用是安全要同时守的三条轴；正确提交的分布式事务仍可以泄密、被篡改或被拖垮。</p><footer>—— 据 Anderson, Security Engineering；Stallings 对 CIA 的整理</footer></div><p><a href="/cs/sharding">上一课</a>把数据库课收到水平切分；<a href="/cs/two-pc">两阶段提交</a>已经能跨资源管理器投票。本课不重做 prepare，也不重讲分片键。缺口是：提交可以正确，报文仍可被窃听，页仍可被改而不被发现，服务仍可被请求淹没。操作系统已有<a href="/cs/privilege-rings">特权级</a>与<a href="/cs/kernel-user">内核与用户态</a>，网络已有<a href="/cs/http-tls-entry">TLS 入口</a>；本栏安全课要把这三条轴命名为对象，后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据库课保证的是事务规格，不是敌手模型。2PC 在崩溃假设下原子，并不对抗：链路旁路、伪造参与者、改日志位。缺口因此不是「计算机安全从零讲起」，而是在系统栈已经能算、能存、能传之后，问<strong>对谁保密、对什么完整、对谁可用</strong>。没有这三轴，后课密码与访问控制没有要保护的性质。</p><p><span class="marginnote">完整性这里指数据与控制流未被未授权改写，与 ACID 的 C（约束）不是同一个词。可用则与 DoS 课相接，不是「磁盘没满」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把需求写成 CIA 的组合，而不是一句「要安全」。保密：未授权者得不到明文含义。完整：未授权改动可被检测（有时还可恢复）。可用：授权者在设计的故障与负载模型下仍能用。三者互相挤：加密与认证加延迟，可用策略可能要求降级保密。本课不引入具体算法，只锁定三维规格。</p>',8)),(e(),n(A,null,{default:t(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TPC%5B%222PC%20%E6%AD%A3%E7%A1%AE%E6%8F%90%E4%BA%A4%22%5D%20--%3E%20CIA%5B%22CIA%20%E4%BB%8D%E5%8F%AF%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20CIA%20--%3E%20C%5B%22%E4%BF%9D%E5%AF%86%22%5D%0A%20%20CIA%20--%3E%20I%5B%22%E5%AE%8C%E6%95%B4%22%5D%0A%20%20CIA%20--%3E%20A%5B%22%E5%8F%AF%E7%94%A8%22%5D%0A%20%20CIA%20--%3E%20TM%5B%22%E5%90%8E%E8%AF%BE%3A%20%E5%A8%81%E8%83%81%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>以后密码课分别服务这些轴：对称加密偏保密，MAC 与签名偏完整与认证，副本与限流偏可用。访问控制决定谁算授权。TLS 入口已经把「套上加密管道」放进网络课；本课要说清管道保护的是哪一轴，以及管道之外（端点、内存、侧信道）仍裸着。</p><p>三轴会互相挤：加密加延迟，过滤加误杀。需求里要写清优先保哪一轴。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CIA 不是完备清单。真实性、不可否认、隐私（对推断）常单列。本课不把它们吞进三字母里充数，后课认证与证书会补真实性。也不把「机密性 = 加密」：访问控制与物理隔离同样服务于 C。</p><p>可用失败可以在密码全对时发生：后课 DoS 单独打 A 轴。后课默认：谈到安全需求，先标 CIA 哪几轴；敌手是谁、在哪一层，下一课威胁模型才写。</p><p>后课每一机制都应能指回这三轴之一（或真实性）。做不到的，只是换了一层实现，不是安全课的对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>2PC 的正确性假设诚实而会崩溃的参与者；安全课换敌手。</p></li><li><p>后课威胁模型把「谁能看、改、停」写成后继机制的目标函数。</p></li><li><p>2PC 可以原子；本课补上保密、完整、可用三轴。</p></li><li><p>完整性 ≠ 数据库约束；可用 ≠ 事务吞吐口号。</p></li><li><p>没有敌手画像之前，算法课没有目标函数。</p></li><li><p>出处：Anderson, <em>Security Engineering</em>；Stallings, <em>Cryptography and Network Security</em>。</p></li></ul>',9))])}const T=l(c,[["render",h]]);export{I as __pageData,T as default};
